use crate::bson_values;
use crate::bson_values::Loaded;
use mongodb::bson::Document;
use mongodb::error::Error;

/// A document of the "patients" collection. A field stays `None` until it is set or read.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Patient {
    pub id: Option<String>,
    /// Full name
    pub name: Option<String>,
    pub birth: Option<chrono::DateTime<chrono::Utc>>,
    pub weight: Option<f64>,
    pub balance: Option<rust_decimal::Decimal>,
    pub document: Option<String>,
    pub photo: Option<Vec<u8>>,
    pub visits: Option<i32>,
    pub blood: Option<String>,
    pub contacts: Option<Vec<PatientContact>>,
    pub insurance: Option<PatientInsurance>,
    pub version: Option<i32>,
    /// As it was read: a change writes only what differs
    pub loaded_document: Loaded,
}

impl Patient {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        let mut entity = Patient {
            id: bson_values::read(document, "_id", bson_values::as_object_id)?,
            name: bson_values::read(document, "name", bson_values::as_text)?,
            birth: bson_values::read(document, "birth", bson_values::as_moment)?,
            weight: bson_values::read(document, "weight", bson_values::as_f64)?,
            balance: bson_values::read(document, "balance", bson_values::as_decimal)?,
            document: bson_values::read(document, "document", bson_values::as_text)?,
            photo: bson_values::read(document, "photo", bson_values::as_bytes)?,
            visits: bson_values::read(document, "visits", bson_values::as_i32)?,
            blood: bson_values::read(document, "blood", bson_values::as_text)?,
            contacts: bson_values::read(document, "contacts", bson_values::as_list(bson_values::as_nested(PatientContact::from_document)))?,
            insurance: bson_values::read(document, "insurance", bson_values::as_nested(PatientInsurance::from_document))?,
            version: bson_values::read(document, "version", bson_values::as_i32)?,
            loaded_document: Loaded::default(),
        };
        entity.loaded_document = Loaded(Some(entity.to_document()?));
        Ok(entity)
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "_id", &self.id, bson_values::of_object_id)?;
        bson_values::write(&mut document, "name", &self.name, bson_values::of_text)?;
        bson_values::write(&mut document, "birth", &self.birth, bson_values::of_moment)?;
        bson_values::write(&mut document, "weight", &self.weight, bson_values::of_f64)?;
        bson_values::write(&mut document, "balance", &self.balance, bson_values::of_decimal)?;
        bson_values::write(&mut document, "document", &self.document, bson_values::of_text)?;
        bson_values::write(&mut document, "photo", &self.photo, bson_values::of_bytes)?;
        bson_values::write(&mut document, "visits", &self.visits, bson_values::of_i32)?;
        bson_values::write(&mut document, "blood", &self.blood, bson_values::of_text)?;
        bson_values::write(&mut document, "contacts", &self.contacts, bson_values::of_list(bson_values::of_nested(PatientContact::to_document)))?;
        bson_values::write(&mut document, "insurance", &self.insurance, bson_values::of_nested(PatientInsurance::to_document))?;
        bson_values::write(&mut document, "version", &self.version, bson_values::of_i32)?;
        Ok(document)
    }
}

/// A nested document: it is stored with the one that holds it.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct PatientContact {
    pub kind: Option<String>,
    pub value: Option<String>,
}

impl PatientContact {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        Ok(PatientContact {
            kind: bson_values::read(document, "kind", bson_values::as_text)?,
