//! The repositories of the "patients" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::bson_values;
use crate::bson_values::Loaded;
use crate::common::CursorPage;
use crate::database::Db;
use crate::entities::patient::Patient;
use crate::errors::DomainError;
use mongodb::bson::doc;
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where patients rows are kept. Services depend only on this trait.
#[async_trait]
pub trait PatientRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: String) -> Result<Option<Patient>, DomainError>;

    /// At most limit rows after the key after (None for the first page), by primary key, and the key to read the next page from.
    async fn list(&self, after: Option<String>, limit: u64) -> Result<CursorPage<Patient, String>, DomainError>;

    /// The row with this document, or None.
    async fn find_by_document(&self, document: String) -> Result<Option<Patient>, DomainError>;

    /// Rows with this birth, by primary key.
    async fn find_all_by_birth(&self, birth: chrono::DateTime<chrono::Utc>) -> Result<Vec<Patient>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Patient) -> Result<Patient, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Patient) -> Result<Patient, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Patient) -> Result<(), DomainError>;

    /// Adds an item to contacts, and gives the row as it is then, if there is one.
    async fn add_contact(&self, id: String, contact: crate::entities::patient::PatientContact) -> Result<Option<Patient>, DomainError>;

    /// Removes an item from contacts that has this size, and gives the row as it is then, if there is one.
    async fn remove_contact(&self, id: String, position: usize, size: usize) -> Result<Option<Patient>, DomainError>;
}

/// Keeps patients rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoPatientRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoPatientRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl PatientRepository for MongoPatientRepository<'_> {
    async fn find_by_id(&self, id: String) -> Result<Option<Patient>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let found = self.db.find_one("patients", doc! { "_id": bson_values::of_object_id(&id)? }).await?;
        Ok(found.as_ref().map(Patient::from_document).transpose()?)
    }

    async fn list(&self, after: Option<String>, limit: u64) -> Result<CursorPage<Patient, String>, DomainError> {
        let mut filter = doc! {};
        if let Some(after) = after {
            filter.insert("_id", doc! { "$gt": bson_values::of_object_id(&after)? });
        }
        let found = self.db.find("patients", filter, doc! { "_id": 1 }, 0, limit + 1).await?;
        let mut items: Vec<Patient> = found.iter().map(Patient::from_document).collect::<Result<_, _>>()?;
        let more = items.len() as u64 > limit;
        items.truncate(limit as usize);
        let next = if more { items.last().map(|last| last.id.clone().expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn find_by_document(&self, document: String) -> Result<Option<Patient>, DomainError> {
        let found = self.db.find_one("patients", doc! { "document": bson_values::of_text(&document)? }).await?;
        Ok(found.as_ref().map(Patient::from_document).transpose()?)
    }

    async fn find_all_by_birth(&self, birth: chrono::DateTime<chrono::Utc>) -> Result<Vec<Patient>, DomainError> {
        let found = self.db.find("patients", doc! { "birth": bson_values::of_moment(&birth)? }, doc! { "_id": 1 }, 0, 0).await?;
        Ok(found.iter().map(Patient::from_document).collect::<Result<_, _>>()?)
    }

    async fn insert(&self, entity: Patient) -> Result<Patient, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        let document = entity.to_document()?;
        self.db.insert("Patient", "patients", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Patient) -> Result<Patient, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["name", "birth", "weight", "balance", "document", "photo", "visits", "blood", "contacts", "insurance", "version"]);
        if !changes.is_empty() {
            self.db.update("Patient", "patients", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Patient) -> Result<(), DomainError> {
        let id = entity.id.clone().expect("id is set");
        self.db.delete("Patient", "patients", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }

    async fn add_contact(&self, id: String, contact: crate::entities::patient::PatientContact) -> Result<Option<Patient>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$push": { "contacts": bson_values::of_nested(crate::entities::patient::PatientContact::to_document)(&contact)? }, "$inc": { "version": 1 } };
        let changed = self.db.change("Patient", "patients", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Patient::from_document).transpose()?)
    }

    async fn remove_contact(&self, id: String, position: usize, size: usize) -> Result<Option<Patient>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let head = doc! { "$slice": ["$contacts", position as i64] };
        let tail = doc! { "$slice": ["$contacts", position as i64 + 1, size.max(1) as i64] };
        let change = vec![doc! { "$set": { "contacts": { "$concatArrays": [head, tail] }, "version": { "$add": ["$version", 1] } } }];
        let changed = self.db.change("Patient", "patients", doc! { "_id": bson_values::of_object_id(&id)?, "contacts": { "$size": size as i64 } }, change).await?;
        Ok(changed.as_ref().map(Patient::from_document).transpose()?)
    }
}

/// Keeps patients rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryPatientRepository {
    rows: Arc<Mutex<Vec<Patient>>>,
}

impl MemoryPatientRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Patient> {
        let mut rows: Vec<Patient> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Patient) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Patient) -> (Option<String>,) {
    (row.id.clone(),)
}

#[async_trait]
impl PatientRepository for MemoryPatientRepository {
    async fn find_by_id(&self, id: String) -> Result<Option<Patient>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, after: Option<String>, limit: u64) -> Result<CursorPage<Patient, String>, DomainError> {
        let after = after.map(|after| (Some(after),));
        let rows: Vec<_> = self
            .visible()
            .into_iter()
            .filter(|row| after.as_ref().is_none_or(|after| key_of(row).partial_cmp(after) == Some(Ordering::Greater)))
            .collect();
        let more = rows.len() as u64 > limit;
        let items: Vec<Patient> = rows.into_iter().take(limit as usize).collect();
        let next = if more { items.last().map(|last| last.id.clone().expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn find_by_document(&self, document: String) -> Result<Option<Patient>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.document.as_ref() == Some(&document)))
    }

    async fn find_all_by_birth(&self, birth: chrono::DateTime<chrono::Utc>) -> Result<Vec<Patient>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.birth.as_ref() == Some(&birth)).collect())
    }

    async fn insert(&self, entity: Patient) -> Result<Patient, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Patient) -> Result<Patient, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Patient) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }

    async fn add_contact(&self, id: String, contact: crate::entities::patient::PatientContact) -> Result<Option<Patient>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.contacts.get_or_insert_default().push(contact);
        found.version = Some(found.version.unwrap_or(0) + 1);
        self.store(&found);
        Ok(Some(found))
    }

    async fn remove_contact(&self, id: String, position: usize, size: usize) -> Result<Option<Patient>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        let items = found.contacts.get_or_insert_default();
        if items.len() != size || position >= size {
            return Ok(None);
        }
        items.remove(position);
        found.version = Some(found.version.unwrap_or(0) + 1);
        self.store(&found);
        Ok(Some(found))
    }
}

