//! The repositories of the "rooms" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::bson_values;
use crate::bson_values::Loaded;
use crate::common::CursorPage;
use crate::database::Db;
use crate::entities::room::Room;
use crate::errors::DomainError;
use mongodb::bson::doc;
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where rooms rows are kept. Services depend only on this trait.
#[async_trait]
pub trait RoomRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: String) -> Result<Option<Room>, DomainError>;

    /// At most limit rows after the key after (None for the first page), by primary key, and the key to read the next page from.
    async fn list(&self, after: Option<String>, limit: u64) -> Result<CursorPage<Room, String>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Room) -> Result<Room, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Room) -> Result<Room, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Room) -> Result<(), DomainError>;
}

/// Keeps rooms rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoRoomRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoRoomRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl RoomRepository for MongoRoomRepository<'_> {
    async fn find_by_id(&self, id: String) -> Result<Option<Room>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let found = self.db.find_one("rooms", doc! { "_id": bson_values::of_object_id(&id)? }).await?;
        Ok(found.as_ref().map(Room::from_document).transpose()?)
    }

    async fn list(&self, after: Option<String>, limit: u64) -> Result<CursorPage<Room, String>, DomainError> {
        let mut filter = doc! {};
        if let Some(after) = after {
            filter.insert("_id", doc! { "$gt": bson_values::of_object_id(&after)? });
        }
        let found = self.db.find("rooms", filter, doc! { "_id": 1 }, 0, limit + 1).await?;
        let mut items: Vec<Room> = found.iter().map(Room::from_document).collect::<Result<_, _>>()?;
        let more = items.len() as u64 > limit;
        items.truncate(limit as usize);
        let next = if more { items.last().map(|last| last.id.clone().expect("id is set")) } else { None };
        Ok(CursorPage { items, next })
    }

    async fn insert(&self, entity: Room) -> Result<Room, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        let document = entity.to_document()?;
        self.db.insert("Room", "rooms", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Room) -> Result<Room, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["code", "beds"]);
        if !changes.is_empty() {
            self.db.update("Room", "rooms", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Room) -> Result<(), DomainError> {
        let id = entity.id.clone().expect("id is set");
        self.db.delete("Room", "rooms", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }
}

