//! The service of the "patients" table.

use crate::common::CursorPage;
use crate::dtos::patient::{PatientCreate, PatientRead, PatientUpdate};
use crate::entities::patient::Patient;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on patients. Each write runs in a transaction of its own.
pub struct PatientService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl PatientService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Patient after checking it.
    pub async fn create_patient(&self, data: PatientCreate) -> Result<PatientRead, DomainError> {
        let values = Values { name: data.name.map(Some), birth: data.birth.map(Some), weight: data.weight.map(Some), balance: data.balance.map(Some), document: data.document.map(Some), photo: data.photo.map(Some), visits: data.visits.map(Some), blood: data.blood.map(Some), contacts: data.contacts.map(Some), insurance: data.insurance.map(Some), version: data.version.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Patient::default();
        apply_values(&mut entity, &values);
        let created = uow.patients().insert(entity).await?;
        transaction.commit().await?;
        Ok(read(created))
    }

    /// The Patient with this key; NotFound when there is none.
    pub async fn get_patient(&self, id: String) -> Result<PatientRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// A page of patients after the key after (None for the first page), by primary key.
    pub async fn list_patients(&self, after: Option<String>, limit: u64) -> Result<CursorPage<PatientRead, String>, DomainError> {
        self.unit_of_work.patients().list(after, limit).await.map(|page| page.map(read))
    }

    /// Changes the given values of a Patient, read at version.
    pub async fn update_patient(&self, id: String, changes: PatientUpdate, version: i32) -> Result<PatientRead, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        if current.version != Some(version) {
            return Err(DomainError::conflict("Patient", "was changed by someone else since it was read", &["version"]));
        }
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        current.version = Some(version + 1);
        let updated = uow.patients().update(current).await?;
        transaction.commit().await?;
        Ok(read(updated))
    }

    /// Deletes a Patient.
    pub async fn delete_patient(&self, id: String, version: i32) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        if current.version != Some(version) {
            return Err(DomainError::conflict("Patient", "was changed by someone else since it was read", &["version"]));
        }
        uow.patients().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// The Patient with this document, or None.
    pub async fn find_patient_by_document(&self, document: String) -> Result<Option<PatientRead>, DomainError> {
        self.unit_of_work.patients().find_by_document(document).await.map(|row| row.map(read))
    }

    /// Adds an item to contacts, read at version.
    pub async fn add_contact(&self, id: String, contact: crate::entities::patient::PatientContact, version: i32) -> Result<PatientRead, DomainError> {
        let mut errors: Vec<FieldError> = Vec::new();
        check_patient_contact(&contact, "contacts", &mut errors);
        if !errors.is_empty() {
            return Err(DomainError::ValidationFailed { entity: "Patient".to_string(), errors });
        }
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id.clone()).await?;
        if current.version != Some(version) {
            return Err(DomainError::conflict("Patient", "was changed by someone else since it was read", &["version"]));
        }
        let changed = uow.patients().add_contact(id.clone(), contact).await?.ok_or_else(|| DomainError::not_found("Patient", id))?;
        transaction.commit().await?;
        Ok(read(changed))
    }

    /// Removes an item from contacts, by its position, read at version.
    pub async fn remove_contact(&self, id: String, position: usize, version: i32) -> Result<PatientRead, DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id.clone()).await?;
        if current.version != Some(version) {
            return Err(DomainError::conflict("Patient", "was changed by someone else since it was read", &["version"]));
        }
        if !(position < current.contacts.as_deref().unwrap_or_default().len()) {
            return Err(DomainError::not_found("Contact", position));
        }
        let size = current.contacts.as_deref().unwrap_or_default().len();
        let changed = uow.patients().remove_contact(id.clone(), position, size).await?.ok_or_else(|| DomainError::conflict("Patient", "was changed by someone else since it was read", &["contacts"]))?;
        transaction.commit().await?;
        Ok(read(changed))
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    name: Option<Option<String>>,
    birth: Option<Option<chrono::DateTime<chrono::Utc>>>,
    weight: Option<Option<f64>>,
    balance: Option<Option<rust_decimal::Decimal>>,
    document: Option<Option<String>>,
    photo: Option<Option<Vec<u8>>>,
    visits: Option<Option<i32>>,
    blood: Option<Option<String>>,
    contacts: Option<Option<Vec<crate::entities::patient::PatientContact>>>,
    insurance: Option<Option<crate::entities::patient::PatientInsurance>>,
    version: Option<Option<i32>>,
}

/// Checks the values against the rules of the "patients" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Patient>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.name.is_some() {
                errors.push(FieldError::new("name", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 80 {
                errors.push(FieldError::new("name", "is longer than 80 characters"));
            }
            if !(value.as_str().chars().count() >= 2) {
                errors.push(FieldError::new("name", "must have >= 2 characters"));
            }
        }
    }
    match values.birth.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.birth.is_some() {
                errors.push(FieldError::new("birth", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.visits.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.visits.is_some() {
                errors.push(FieldError::new("visits", "is required"));
            }
        }
        Some(value) => {
            if !((*value as f64) >= 0.0) {
                errors.push(FieldError::new("visits", "must be >= 0"));
            }
        }
    }
    if let Some(value) = values.blood.as_ref().and_then(|value| value.as_ref()) {
        if !["A", "B", "O"].contains(&value.as_str()) {
            errors.push(FieldError::new("blood", "must be one of: A, B, O"));
        }
    }
    match values.contacts.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.contacts.is_some() {
                errors.push(FieldError::new("contacts", "is required"));
            }
        }
        Some(value) => {
            for (i0, item0) in value.iter().enumerate() {
                check_patient_contact(item0, &format!("contacts.{i0}"), &mut errors);
            }
        }
    }
    if let Some(value) = values.insurance.as_ref().and_then(|value| value.as_ref()) {
        check_patient_insurance(value, "insurance", &mut errors);
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Patient".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Patient>) -> Result<(), DomainError> {
    {
        let document = values.document.clone().unwrap_or_else(|| current.and_then(|current| current.document.clone()));
        if let Some(document) = document {
            if let Some(other) = uow.patients().find_by_document(document).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Patient", "document is already taken", &["document"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Patient>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Patient, values: &Values) {
    if let Some(value) = &values.name {
        entity.name = value.clone();
    }
    if let Some(value) = &values.birth {
        entity.birth = *value;
    }
    if let Some(value) = &values.weight {
        entity.weight = *value;
    }
    if let Some(value) = &values.balance {
        entity.balance = *value;
    }
    if let Some(value) = &values.document {
        entity.document = value.clone();
    }
    if let Some(value) = &values.photo {
        entity.photo = value.clone();
    }
    if let Some(value) = &values.visits {
        entity.visits = *value;
    }
    if let Some(value) = &values.blood {
        entity.blood = value.clone();
    }
    if let Some(value) = &values.contacts {
        entity.contacts = value.clone();
    }
    if let Some(value) = &values.insurance {
        entity.insurance = value.clone();
    }
    if let Some(value) = &values.version {
        entity.version = *value;
    }
}

/// What a PatientContact does not follow of its rules, each with the path of its field.
fn check_patient_contact(value: &crate::entities::patient::PatientContact, path: &str, errors: &mut Vec<FieldError>) {
    if let Some(held) = &value.kind {
        if !["phone", "email"].contains(&held.as_str()) {
            errors.push(FieldError::new(&format!("{path}.kind"), "must be one of: phone, email"));
        }
    } else {
        errors.push(FieldError::new(&format!("{path}.kind"), "is required"));
    }
    if value.value.is_none() {
        errors.push(FieldError::new(&format!("{path}.value"), "is required"));
    }
}

/// What a PatientInsurance does not follow of its rules, each with the path of its field.
fn check_patient_insurance(_value: &crate::entities::patient::PatientInsurance, _path: &str, _errors: &mut Vec<FieldError>) {
}

/// The values an update gives, by field.
fn given(changes: PatientUpdate) -> Values {
    Values { name: Some(Some(changes.name)), birth: Some(Some(changes.birth)), weight: Some(changes.weight), balance: Some(changes.balance), document: Some(changes.document), photo: Some(changes.photo), visits: Some(Some(changes.visits)), blood: Some(changes.blood), contacts: Some(Some(changes.contacts)), insurance: Some(changes.insurance), version: Some(changes.version) }
}

/// The Patient with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Patient, DomainError> {
    uow.patients().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Patient", id))
}

/// The Patient as services return it.
fn read(entity: Patient) -> PatientRead {
    PatientRead {
        id: entity.id.expect("id is set"),
        name: entity.name.expect("name is set"),
        birth: entity.birth.expect("birth is set"),
        weight: entity.weight,
        balance: entity.balance,
        document: entity.document,
        photo: entity.photo,
        visits: entity.visits.expect("visits is set"),
        blood: entity.blood,
        contacts: entity.contacts.expect("contacts is set"),
        insurance: entity.insurance,
        version: entity.version,
    }
}

