//! The service of the "rooms" table.

use crate::common::CursorPage;
use crate::dtos::room::{RoomCreate, RoomRead, RoomUpdate};
use crate::entities::room::Room;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on rooms. Each write runs in a transaction of its own.
pub struct RoomService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl RoomService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Room after checking it.
    pub async fn create_room(&self, data: RoomCreate) -> Result<RoomRead, DomainError> {
        let values = Values { code: data.code.map(Some), beds: data.beds.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Room::default();
        apply_values(&mut entity, &values);
        let created = uow.rooms().insert(entity).await?;
        transaction.commit().await?;
        Ok(read(created))
    }

    /// The Room with this key; NotFound when there is none.
    pub async fn get_room(&self, id: String) -> Result<RoomRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// A page of rooms after the key after (None for the first page), by primary key.
    pub async fn list_rooms(&self, after: Option<String>, limit: u64) -> Result<CursorPage<RoomRead, String>, DomainError> {
        self.unit_of_work.rooms().list(after, limit).await.map(|page| page.map(read))
    }

    /// Changes the given values of a Room.
    pub async fn update_room(&self, id: String, changes: RoomUpdate) -> Result<RoomRead, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.rooms().update(current).await?;
        transaction.commit().await?;
        Ok(read(updated))
    }

    /// Deletes a Room.
    pub async fn delete_room(&self, id: String) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        uow.rooms().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    code: Option<Option<String>>,
    beds: Option<Option<i64>>,
}

/// Checks the values against the rules of the "rooms" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Room>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.code.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.code.is_some() {
                errors.push(FieldError::new("code", "is required"));
            }
        }
        Some(_) => {}
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Room".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Room>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Room, values: &Values) {
    if let Some(value) = &values.code {
        entity.code = value.clone();
    }
    if let Some(value) = &values.beds {
        entity.beds = *value;
    }
}

/// The values an update gives, by field.
fn given(changes: RoomUpdate) -> Values {
    Values { code: Some(Some(changes.code)), beds: Some(changes.beds) }
}

/// The Room with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Room, DomainError> {
    uow.rooms().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Room", id))
}

/// The Room as services return it.
fn read(entity: Room) -> RoomRead {
    RoomRead {
        id: entity.id.expect("id is set"),
        code: entity.code.expect("code is set"),
        beds: entity.beds,
    }
}

