//! The repository of the "patients" table, against the test database.

use mongorust_mongodb_validators_dtos::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_patient(&uow, 1).await;
    let found = uow.patients().find_by_id(stored.id.clone().expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
    if stored.document.is_some() {
        assert!(uow.patients().find_by_document(stored.document.clone().expect("document is set")).await.expect("a read").is_some());
    }
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_patient(&uow, 1).await;
    factories::add_patient(&uow, 2).await;
    let first = uow.patients().list(None, 1).await.expect("a page");
    assert_eq!(1, first.items.len());
    assert!(first.next.is_some());
    let second = uow.patients().list(first.next, 1).await.expect("a page");
    assert_eq!(1, second.items.len());
    assert!(second.next.is_none());
}

