    assert!(uow.patients().find_by_id(stored.id.clone().expect("id is set")).await.expect("a read").is_none());
}

#[tokio::test]
async fn adds_and_removes_one_item_of_contacts() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_patient(&uow, 1).await;
    let before = stored.contacts.as_ref().map_or(0, Vec::len);
    let n = 7;
    let item: mongorust_mongodb_validators_dtos::entities::patient::PatientContact = factories::new_patient_contact(n);
    let added = uow.patients().add_contact(stored.id.clone().expect("id is set"), item).await.expect("a write").expect("the row");
    assert_eq!(before + 1, added.contacts.as_ref().map_or(0, Vec::len));
    let removed = uow.patients().remove_contact(stored.id.clone().expect("id is set"), before, added.contacts.as_ref().map_or(0, Vec::len)).await.expect("a write").expect("the row");
    assert_eq!(before, removed.contacts.as_ref().map_or(0, Vec::len));
    assert!(uow.patients().remove_contact(stored.id.clone().expect("id is set"), 0, before + 5).await.expect("a write").is_none());
}

