    let row = factories::new_patient(1);
    let first = service.create_patient(create_of(row)).await.expect("a create");
    let mut again = factories::new_patient(2);
    again.document = first.document.clone();
    assert!(matches!(service.create_patient(create_of(again)).await, Err(DomainError::Conflict { .. })));
}

#[tokio::test]
async fn keeps_its_own_unique_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = PatientService::new(uow.clone());
    let row = factories::new_patient(1);
    let created = service.create_patient(create_of(row.clone())).await.expect("a create");
    let updated = service.update_patient(created.id.clone(), PatientUpdate { name: row.name.clone().expect("name is set"), birth: row.birth.expect("birth is set"), weight: row.weight, balance: row.balance, document: created.document.clone(), photo: row.photo.clone(), visits: row.visits.expect("visits is set"), blood: row.blood.clone(), contacts: row.contacts.clone().expect("contacts is set"), insurance: row.insurance.clone(), version: row.version }, created.version.expect("version is set")).await.expect("an update");
    assert_eq!(created.document, updated.document);
}

#[tokio::test]
async fn says_when_a_row_is_missing() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = PatientService::new(uow.clone());
    assert!(matches!(service.get_patient("ffffffffffffffffffffffff".to_string()).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn deletes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = PatientService::new(uow.clone());
    let row = factories::new_patient(1);
    let created = service.create_patient(create_of(row)).await.expect("a create");
    service.delete_patient(created.id.clone(), created.version.expect("version is set")).await.expect("a delete");
    assert!(matches!(service.get_patient(created.id.clone()).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn adds_and_removes_one_item_of_contacts() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = PatientService::new(uow.clone());
    let row = factories::new_patient(1);
    let created = service.create_patient(create_of(row)).await.expect("a create");
    let before = created.contacts.len();
    let n = 7;
    let item: mongorust_mongodb_validators_dtos::entities::patient::PatientContact = factories::new_patient_contact(n);
    let added = service.add_contact(created.id.clone(), item, created.version.expect("version is set")).await.expect("a write");
    assert_eq!(before + 1, added.contacts.len());
    let removed = service.remove_contact(created.id.clone(), before, added.version.expect("version is set")).await.expect("a write");
    assert_eq!(before, removed.contacts.len());
    assert!(matches!(service.remove_contact(created.id.clone(), 99, removed.version.expect("version is set")).await, Err(DomainError::NotFound { .. })));
}

/// The create DTO of a row the factories made.
fn create_of(row: Patient) -> PatientCreate {
    PatientCreate { name: row.name, birth: row.birth, weight: row.weight, balance: row.balance, document: row.document, photo: row.photo, visits: row.visits, blood: row.blood, contacts: row.contacts, insurance: row.insurance, version: row.version }
}

