    let created = service.create_room(create_of(row)).await.expect("a create");
    service.delete_room(created.id.clone()).await.expect("a delete");
    assert!(matches!(service.get_room(created.id.clone()).await, Err(DomainError::NotFound { .. })));
}

/// The create DTO of a row the factories made.
fn create_of(row: Room) -> RoomCreate {
    RoomCreate { code: row.code, beds: row.beds }
}
